import {cureHangarConversation} from '../../src/data/l10Story';
import { cureEncounterSpot } from '../../src/levels/L10/encounters';
import {insideCureHangar} from '../../src/data/l10Story';
import { runLevel } from '../sim-runner/levels';
import { preset } from '../../src/sim/progression/Campaign';
import { observeAttackStarts } from './threat/attackStarts';
const receipts=[];for(const seed of [1,2,3])for(const quality of ['low','high'] as const){
let lastStart=0;let totalTicks=0,peak=0,previousDialogue=0;const protectedTicks:number[]=[];let pulseAdmissions=0;const starts:Array<{t:number,x:number,z:number}>=[]; const marks:Array<{t:number,x:number,z:number}>=[];
const result=await runLevel('L10','complete',seed,1800,'auto',preset('L10-default'),undefined,0,{quality,beforeBegin(world){observeAttackStarts(world,(_id,target,tick)=>{if(target===1){lastStart=tick;const p=world.entities.get(1)!.transform;starts.push({t:tick/60,x:+p.x.toFixed(0),z:+p.z.toFixed(0)});}});world.events.on('sim.tick',e=>{if(e.type==='sim.tick'){totalTicks=e.tick;peak=Math.max(peak,world.infected!.director.count);const c=world.missions!.state.counters;const progress=cureHangarConversation.slice(0,c['hangar-line']??0).reduce((n,l)=>n+l[1],0)+(c['hangar-line-ticks']??0);if(progress>previousDialogue)protectedTicks.push(e.tick);previousDialogue=progress;}if(e.type==='sim.tick'&&e.tick%300===0&&e.tick-lastStart>=900&&!world.missions!.state.states['cure-installed']&&!world.storyLock){const ai=world.infected!,p=world.entities.get(1)!.transform;const at={x:p.x+40,z:p.z};if(ai.pool.length&&ai.director.count<ai.director.cap-ai.director.reserved-ai.director.pendingTurns-1&&world.chunks!.resident(at.x,at.z)){for(const offset of [-7,-5,-3,-1,1,3,5,7]){const point=cureEncounterSpot(ai.nav,{x:at.x,z:at.z+offset,archetype:'infected.sprinter'},(x,z)=>!insideCureHangar({x,z})&&world.chunks!.resident(x,z)&&ai.director.safe('infected.sprinter',{x,z}),33);if(!point)continue;if(ai.director.safe('infected.sprinter',point))if(ai.director.count<ai.director.cap-ai.director.reserved-ai.director.pendingTurns-1&&ai.pool.length&&ai.nav.clear(point.x,point.z,.35)){const id=ai.spawn('infected.sprinter',point,{state:'chase'});ai.pursueTarget(id,1);pulseAdmissions++;}}}} if(e.type==='sim.tick'&&e.tick%600===0){const p=world.entities.get(1)!.transform;marks.push({t:e.tick/60,x:+p.x.toFixed(0),z:+p.z.toFixed(0)});}});}});
const gaps=starts.slice(1).map((s,i)=>({from:starts[i].t,to:s.t,seconds:s.t-starts[i].t-protectedTicks.filter(t=>t>starts[i].t*60&&t<=s.t*60).length/60}));receipts.push({seed,quality,completed:result.completed,deaths:result.deaths,pulseAdmissions,peak,totalTicks,protectedSeconds:protectedTicks.length/60,n:starts.length,rate:starts.length/((totalTicks/60-starts[0].t)/60),maxGap:Math.max(...gaps.map(g=>g.seconds)),gaps:gaps.filter(g=>g.seconds>45)});console.error(JSON.stringify(receipts.at(-1)));}
